// Count all unordered pairs of supports, not just maximal supports. Input graph6 u v per line.
use std::{io::{self,BufRead},collections::HashMap};
fn main(){for l in io::stdin().lock().lines(){let l=l.unwrap();let mut it=l.split_whitespace();let b=it.next().unwrap().as_bytes();let u:usize=it.next().unwrap().parse().unwrap();let v:usize=it.next().unwrap().parse().unwrap();let e=(1u32<<u)|(1<<v);let mut a=[0u32;27];let mut t=0;for j in 0..27{for i in 0..j{if (b[1+t/6]-63)>>(5-t%6)&1!=0{a[i]|=1<<j;a[j]|=1<<i}t+=1}}let mut rows=vec![0u32];for i in 0..27{for k in 0..rows.len(){let r=rows[k];if r&a[i]==0{rows.push(r|(1<<i))}}}let qs:Vec<_>=rows.iter().copied().filter(|r|r.count_ones()==7).collect();rows.retain(|r|r&e!=e);a[u]|=1<<v;a[v]|=1<<u;let maxi:Vec<_>=rows.iter().enumerate().filter(|(_,r)|(0..27).all(|j|**r&(a[j]|(1<<j))!=0)).map(|(j,_)|j).collect();let idx:HashMap<u32,usize>=rows.iter().enumerate().map(|(i,&r)|(r,i)).collect();let w=(qs.len()+63)/64;let mut miss=vec![0u64;w*rows.len()];let mut dead=vec![0u64;w];for(j,&q)in qs.iter().enumerate(){if q&e==e{dead[j/64]|=1<<(j%64)}for(i,&s)in rows.iter().enumerate(){if q&s==0{miss[i*w+j/64]|=1<<(j%64)}}}let mut seen=vec![0;rows.len()];let mut total=0u64;for i in 0..rows.len(){let live:Vec<_>=(0..w).map(|h|miss[i*w+h]&!dead[h]).collect();let broken:Vec<_>=(0..w).map(|h|miss[i*w+h]&dead[h]).collect();if broken.iter().all(|&m|m==0){continue}let legal=|j:usize|(0..w).all(|h|live[h]&miss[j*w+h]==0);for &m in &maxi{if m<i||!legal(m){continue}let mut sub=rows[m];loop{let j=idx[&sub];if j>=i && seen[j]!=i+1{seen[j]=i+1;if legal(j)&&(0..w).any(|h|broken[h]&miss[j*w+h]!=0){total+=1}}if sub==0{break}sub=(sub-1)&rows[m]}}}println!("{}",total)}}
